
/* ---- GRAFICA DI PROVA: sprite d'arte (WebP incorporati) al posto di quelli disegnati a codice ---- */
GfxNew.art=function(){
  // variants: [{f:specchia, fl:filtro}]
  const mkArt=(b64,lw,lh,ax,ay,vars)=>{
    const img=new Image(),out=vars.map(v=>{const[c,x]=mk(lw,lh);return{c,w:lw,h:lh,ax,ay,_x:x,art:1}});
    img.onload=()=>{out.forEach((s,i)=>{const x=s._x,v=vars[i];x.clearRect(0,0,lw,lh);
      x.save();if(v.f){x.translate(lw,0);x.scale(-1,1)}if(v.fl)x.filter=v.fl;x.drawImage(img,0,0,lw,lh);x.restore();
      const[c2,x2]=mk(lw,lh);x2.drawImage(s.c,0,0,lw,lh);x2.globalCompositeOperation='source-in';x2.fillStyle='#0e1c0a';x2.fillRect(0,0,lw,lh);s.sh=c2})};
    img.src='data:image/webp;base64,'+b64;return out;
  };
  const pal=mkArt("",151,165,69,164,[{},{f:1},{fl:'brightness(1.04) saturate(1.05)'}]);
  const palC=pal.map(s=>{const[c,x]=mk(151,165);return{c,w:151,h:165,ax:s.ax,ay:s.ay,_x:x,art:1}});
  const upd=()=>{palC.forEach((s,i)=>{s.sh=pal[i].sh;const x=s._x;x.clearRect(0,0,151,165);x.drawImage(pal[i].c,0,0,151,165);
    const mx=(i%2)?151-73.5:73.5;for(const[ox,oy]of[[-8,6],[6,9],[-1,16]]){ball(x,mx+ox,62+oy,5,'#b99a68','#6a4a26','#3a2612','rgba(30,18,8,.7)')}})};
  const t0=setInterval(upd,300);setTimeout(()=>clearInterval(t0),4000);
  SP.palm=palC;SP.palm0=pal;
  const tA=mkArt("",115,140,58,139,[{},{f:1,fl:'brightness(.96) saturate(1.04)'},{fl:'brightness(1.04) saturate(.95)'},{f:1,fl:'brightness(.93) saturate(1.06)'}]);
  const tB=mkArt("",122,150,58,149,[{},{f:1,fl:'brightness(.96) saturate(1.04)'},{fl:'brightness(1.04) saturate(.95)'},{f:1,fl:'brightness(.93) saturate(1.06)'}]);
  SP.tree=[tA[0],tB[0],tA[1],tB[1],tA[2],tB[2],tA[3],tB[3]];
  SP.pine=mkArt("",113,160,56.5,159,[{},{f:1,fl:'brightness(.96) saturate(1.04)'},{fl:'brightness(1.05) saturate(.95)'},{f:1,fl:'brightness(.93) saturate(1.06)'},{fl:'brightness(.98) saturate(1.02)'}]);
  const rA=mkArt("",57,80,28.5,78,[{},{f:1,fl:'brightness(.97)'},{fl:'brightness(1.04) saturate(.95)'}]);
  const rB=mkArt("",45,46,22.5,44,[{},{f:1,fl:'brightness(.97)'}]);
  SP.boulder=[rA[0],rB[0],rA[1],rB[1],rA[2]];
  SP.stump=mkArt("",30,21,15,18,[{}])[0];
  const bV=[{},{f:1,fl:'brightness(.96) saturate(1.04)'},{fl:'brightness(1.04) saturate(.96)'}];
  SP.berry=mkArt("",64,59,32,57,bV);SP.berry0=mkArt("",64,59,32,57,[{}])[0];
  SP.bush=mkArt("",64,60,32,58,bV);SP.bush0=mkArt("",64,60,32,58,[{fl:'saturate(.5) brightness(.92)'}])[0];
  { const G=new Image();G.src="data:image/webp;base64,";GfxNew.gimg=G; }
  { const B=new Image(),[wc,wx]=mk(430,330);
    B.onload=()=>{wx.clearRect(0,0,430,330);wx.fillStyle='rgba(0,0,0,.2)';wx.beginPath();wx.ellipse(215,282,150,20,0,0,7);wx.fill();wx.drawImage(B,50,19,330,263)};
    B.src="data:image/webp;base64,";SP.wreck={c:wc,w:430,h:330,ax:215,ay:284,art:1}; }
};
